<script setup lang="ts">
const api=useApi(); const { data: subs }=await useAsyncData('admin-subs',()=>api.request<any[]>('/admin/subscriptions').catch(()=>[])); const { data: plans }=await useAsyncData('admin-plans',()=>api.request<any[]>('/admin/plans').catch(()=>[]))
const total=computed(()=> (subs.value||[]).filter(s=>s.status==='active').reduce((a,s)=>a+Number(s.annualValue||0),0))
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">Recurring revenue</p><h1 class="mt-1 font-display text-[32px] tracking-[-.04em]">Subscriptions.</h1><p class="mt-1 text-[11.5px] text-ink/45">Annual integrity plans and mileage tiers.</p></div><div class="mb-4 grid gap-3 sm:grid-cols-3"><div class="rounded-xl bg-ink p-4 text-bone"><p class="font-mono text-[7.5px] uppercase tracking-[.08em] text-bone/35">Active ARR</p><p class="mt-2 font-display text-[27px]">{{ money(total) }}</p></div><div class="a-card p-4"><p class="font-mono text-[7.5px] uppercase tracking-[.08em] text-ink/35">Active accounts</p><p class="mt-2 font-display text-[27px]">{{ subs?.filter(s=>s.status==='active').length }}</p></div><div class="a-card p-4"><p class="font-mono text-[7.5px] uppercase tracking-[.08em] text-ink/35">Plans</p><p class="mt-2 font-display text-[27px]">{{ plans?.length }}</p></div></div><div class="grid gap-3 lg:grid-cols-2"><div v-for="s in subs" :key="s._id" class="a-card flex items-center justify-between p-4"><div><p class="font-display text-[18px] capitalize">{{ s.planSlug }}</p><p class="font-mono text-[8px] uppercase tracking-[.06em] text-ink/35">{{ s.miles }} miles · renews {{ shortDate(s.renewsAt) }}</p></div><div class="text-right"><p class="font-display text-[20px]">{{ money(s.annualValue) }}</p><StatusPill :status="s.status"/></div></div></div></div></template>
